/**
 * コロンビアのクイズ。
 *
 * 難易度は1〜10。基準は他の盤面と同じ「その国の外にいる一般的な人が
 * どれくらい答えられそうか」。
 *
 * 既出題材(southamerica/venezuela/peru/world盤)と重ならないよう、
 * バランキージャのカーニバル・黄金の毒ガエル・シモン・ボリバルの死去地・
 * ワユー族(母系制・織物袋)・グラン・コロンビアの成立〜分裂年・
 * コカ渓谷のワックスヤシは答えにしていない(cities.mjsのヘッダー参照)。
 * 「コロンビアは世界最大のコーヒー輸出国」もsouthamerica盤で既出のため
 * 使わず、別のコーヒーの事実(生産量順位・UNESCO文化的景観)に寄せた。
 *
 * 都市カードに書いた事実(オンダの急流、プエルト・コロンビアの桟橋、
 * ボゴタ/SCADTAの水上機、キブドの多雨、サン・ビセンテの非武装地帯、
 * アラカタカ/マコンド、トゥンハ/ムイスカのサケ、など)は、そのままの形
 * では問わず、別の角度の事実を選んでいる。
 *
 * 難易度9〜10は1問ずつ裏取りした。確度が低いものはコメントに書いた。
 */
function t(source) {
  const parts = source.split("|");
  if (parts.length !== 4) {
    throw new Error(`4言語(en|es|fr|ja)で書いてください: ${source.slice(0, 60)}…`);
  }
  const [en, es, fr, ja] = parts;
  return { en, es, fr, ja };
}

function q(difficulty, question, options, a, fact) {
  return { difficulty, q: t(question), o: options.map(t), a, f: t(fact) };
}

